import java.util.List;
import java.util.Random;

/**
 * This class models grass.
 * Grass can germinate,grow and get eaten by animals.
 * @version 2022.03.02
 */
public class Grass extends Plant
{
    private static final int MAX_GROWTH_STAGES = 3;
    private static final int DEFAULT_STEPS_PER_STAGE = 2;

    private int foodValue;

    /**
     * Returns the food value of the grass.
     * @return int The food value of the grass.
     */
    protected int getFoodValue()
    {
        return foodValue;
    }

    /**
     * Creates grass with a random stage of growth.
     * However, the maximum number of stages is fixed at 3,
     * and the growth rate is fixed at 2 steps per stage.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Grass(Field field, Location location)
    {
        super(field.getRandomProvider(), field, location);

        numberOfStages = MAX_GROWTH_STAGES;
        stepsPerStage = DEFAULT_STEPS_PER_STAGE;
        stageOfGrowth = getRandomProvider().getRandom().nextInt(numberOfStages);
        foodValue = stageOfGrowth;

    }


    /**
     * Make the grass act.
     * The germination rate of grass is affected by weather.
     * @param newGrass To store the newly germinated grass.
     * @param environment The environment that the grass resides in.
     */
    public void act(List<Actor> newGrass, Environment environment)
    {
        Random rand = getRandomProvider().getRandom();
        WeatherService weatherService = environment.getWeatherService();
        if(isAlive()
                && environment.getTime().isDay()
                && weatherService.allowsGrassGermination()
                && rand.nextDouble() <= weatherService.getGrassGerminationRate()) {
            germinate(newGrass);
        }
    }

    /**
     * Check whether this grass is to germinate at this step.
     * New grass will be made into free adjacent locations.
     * @param newGrass A list to return newly made grass.
     */
    protected void germinate(List<Actor> newGrass)
    {
        // New grass are made into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getMovementService().getFreeAdjacentLocations(field, getLocation());
        for(int b = 0; b < free.size(); b++) {
            Location loc = free.remove(0);
            Grass young = field.getOrganismFactory().createOffspring(Grass.class, field, loc);
            newGrass.add(young);
        }
    }

    /**
     * Increment the stage of growth of grass
     * Incrementing the growth also increases the food level by 1
     * @return true If the grass grows.
     * @return false If the grass doesn't grow.
     */
    public boolean incrementGrowth()
    {
        if(super.incrementGrowth()) {
            foodValue++;
            return true;
        }
        return false;
    }

}

/**
 * A class representing shared characteristics of plants.
 *
 * @version 2022.03.02
 */
public abstract class Plant extends Organism implements Actor
{
    // the stages of growth for  plant
    protected int numberOfStages;
    protected int stepsPerStage = 1;
    protected int stageOfGrowth;

    /**
     * Create a new plant at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plant(RandomProvider randomProvider, Field field, Location location)
    {
        super(randomProvider, field, location);
    }

    public int getStepsPerStage()
    {
        return stepsPerStage;
    }

    /**
     * Checks if the plant is still able to growth
     * Returns true and increments the growth of the plant 
     * if the plant hasn't reached its final stage.
     * Returns false otherwise
     */
    public boolean incrementGrowth() {
        if(stageOfGrowth < numberOfStages){
            stageOfGrowth++;
            return true;
        }
        return false;
    }


}

import java.util.List;
import java.util.Random;

/**
 * Centralizes weather state, duration, and weather-driven simulation rules.
 */
public class WeatherService
{
    private static final int FIXED_WEATHER_DURATION = 12;
    private static final int MAX_RANDOM_DURATION = 36;
    private static final double BASE_GRASS_GERMINATION_RATE = 0.1;
    private static final double SUNNY_GRASS_GERMINATION_RATE = 0.15;
    private static final List<WeatherType> WEATHER_TYPES = List.of(
            WeatherType.RAINING,
            WeatherType.SUNNY,
            WeatherType.CLOUDY
    );

    private final RandomProvider randomProvider;

    private Weather currentWeather;
    private int remainingDuration;
    private boolean randomDurationEnabled;

    public WeatherService(RandomProvider randomProvider)
    {
        this.randomProvider = randomProvider;
        reset();
    }

    public Weather getCurrentWeather()
    {
        return currentWeather;
    }

    public WeatherType getCurrentWeatherType()
    {
        return currentWeather.getCurrentWeather();
    }

    public void advance()
    {
        remainingDuration--;
        if(remainingDuration <= 0) {
            currentWeather = new Weather(getRandomWeatherType());
            remainingDuration = getNextDuration();
        }
    }

    public void reset()
    {
        currentWeather = new Weather(WeatherType.SUNNY);
        remainingDuration = getNextDuration();
    }

    public boolean toggleRandomWeatherLength()
    {
        randomDurationEnabled = !randomDurationEnabled;
        remainingDuration = getNextDuration();
        return randomDurationEnabled;
    }

    public boolean canCreateGrassPatches()
    {
        return getCurrentWeatherType() == WeatherType.RAINING;
    }

    public boolean allowsGrassGermination()
    {
        return getCurrentWeatherType() != WeatherType.CLOUDY;
    }

    public double getGrassGerminationRate()
    {
        if(getCurrentWeatherType() == WeatherType.SUNNY) {
            return SUNNY_GRASS_GERMINATION_RATE;
        }
        return BASE_GRASS_GERMINATION_RATE;
    }

    public boolean allowsEagleForaging()
    {
        return getCurrentWeatherType() != WeatherType.RAINING;
    }

    private int getNextDuration()
    {
        if(randomDurationEnabled) {
            return randomProvider.getRandom().nextInt(MAX_RANDOM_DURATION) + 1;
        }
        return FIXED_WEATHER_DURATION;
    }

    private WeatherType getRandomWeatherType()
    {
        Random rand = randomProvider.getRandom();
        return WEATHER_TYPES.get(rand.nextInt(WEATHER_TYPES.size()));
    }
}

